   [59]={next_id=60, abreast_id={}, pType =1, cg_type =0, dialog=1, msg="Would we survive tomorrow? And even if we did, so what... this world was already devoid of hope. Rather than waiting for an unforeseen calamity to turn us into something monstrous... the remaining people decided to embrace death together.", msg_color="", msg_size=0, talker="Uen", audio="", img="arts/ui/bg/story/storybg_802.jpg", video_url="", music_id=0, background_music="", model_tid={{ 2, "7148", 2, 0}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, update_model={{ 2,1}}, role_act={}, head_path="", flash_time=0, shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
